function maximumSum(nums) {
  const largest = new Map();
  let best = -1;

  for (const num of nums) {
    let digitSum = 0;
    for (let rest = num; rest > 0; rest = Math.floor(rest / 10)) {
      digitSum += rest % 10;
    }
    if (largest.has(digitSum)) {
      best = Math.max(best, largest.get(digitSum) + num);
      largest.set(digitSum, Math.max(largest.get(digitSum), num));
    } else {
      largest.set(digitSum, num);
    }
  }
  return best;
}

