function maximumSum(nums) {
  const digits = v => String(v).split('').reduce((total, d) => total + Number(d), 0);
  let best = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (digits(nums[i]) === digits(nums[j])) best = Math.max(best, nums[i] + nums[j]);
  return best;
}

