function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8), top = [9, 60, 500, 1e9][pick(0, 3)];
    return [Array.from({ length: n }, () => pick(1, top))];
  }
  const top = [1e9, 1e5, 1e3][pick(0, 2)];
  return [Array.from({ length: 2000 }, () => pick(1, top))];
}
